var checkPackageExpiration=function(){setTimeout(function(){var n=$(".if-no-payment");n.length>0&&toastr.warning("{0}.".format(JSR.alert_pack_expired),JSR.limit_reached,{timeOut:3e4})},1e3)},showPackageAlert=function(n,t){toastr.warning("<b>{0}<\/b><hr/>{1} : {2} <br/>{3} : <b class='text-lg'>{4}<\/b> {5}.".format(n,JSR.date_end,t,JSR.remaining,JSR.unused_days,JSR.days),JSR.your_subscription,{timeOut:3e4})};$(function(){setTimeout(function(){checkPackageExpiration()},2e3)});